// Real front images: durable local task IDs and ComfyUI outputs.
const frontRequests=new Set();
function frontState(c){return c.frontJob?.status;}
function realImage(c){return c.versions?.[c.active]?.image_url;}
const characterWithRealImages=characters;
characters=function(){characterWithRealImages();const c=data.characters[ci];if(!c)return;const generate=document.querySelector('#generate'),confirm=document.querySelector('#confirm'),multi=document.querySelector('#makeMulti');const status=frontState(c),busy=['submitting','queued','running','waiting'].includes(status);if(generate){generate.textContent=c.view==='multi'?'多面图工作流待接入':busy?({'submitting':'正在提交…','queued':'已排队…','running':'正在生成…','waiting':'正在等待结果…'})[status]:'✦ '+(realImage(c)?'重新生成正面图':'生成正面图');generate.disabled=busy||c.view==='multi';const note=generate.nextElementSibling;if(note)note.textContent='正面图使用本机 Z-Image-Turbo，自定义尺寸、12 步。独立负面提示词已连接采样器，CFG 1.5。';}
if(confirm){confirm.disabled=!realImage(c)||busy;confirm.onclick=()=>{c.confirmed=true;c.confirmedVersion=c.active;save();render();toast('已确认这张真实生成的正面图')}}if(multi){multi.disabled=true;multi.textContent='多面图工作流待接入'}
const preview=document.querySelector('#panel .artboard');if(preview&&c.view!=='multi'&&realImage(c)){preview.replaceChildren();const img=document.createElement('img');img.src=realImage(c);img.alt=c.name+' · ComfyUI 生成的正面图';img.style.cssText='width:100%;height:100%;object-fit:contain;background:#080d14';preview.append(img)}
if(status){const info=document.createElement('p');info.className='subtle';info.setAttribute('role','status');info.textContent=({'submitting':'正在提交本地任务','queued':'已加入 ComfyUI 队列','running':'ComfyUI 正在生成正面图','waiting':'正在等待 ComfyUI 完成','completed':'正面图已生成，图片与工作流已保存到 D:\\AIPlatform\\Output\\DramaStudio','failed':'生成失败：'+(c.frontJob.error||'请检查 ComfyUI')})[status]||status;document.querySelector('#generate')?.after(info)}
};
async function frontFetch(route,body){const r=await fetch(route,{cache:'no-store',method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const result=await r.json();if(!r.ok)throw Error(result.error||'本地生成服务不可用');return result;}
function applyFrontResult(c,job){c.frontJob=job;if(job.status==='completed'&&!c.versions.some(v=>v.job_id===job.id)){c.versions.push({job_id:job.id,time:new Date(job.finished_at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),createdAt:Date.now(),prompt:job.prompt,actual_prompt:job.actual_prompt,negative_prompt:job.negative_prompt,image_url:job.image_url,prompt_id:job.prompt_id});c.active=c.versions.length-1;c.confirmed=false;if(c.multi?.length)c.stale=true;c.reference_images??={};c.reference_images.front=job.image_url;}save();}
generateCharacter=async function(multi){if(multi){toast('多面图还未接入真实工作流');return}const c=data.characters[ci];if(!c||frontRequests.has(c))return;if(['submitting','queued','running','waiting'].includes(frontState(c))){toast('已有任务正在进行，正在继续等待');return}if(!c.prompt?.trim()){toast('请先填写角色正面图提示词');return}frontRequests.add(c);const id=crypto.randomUUID();c.frontJob={id,status:'submitting',created_at:new Date().toISOString()};save();render();try{const job=await frontFetch('/api/front-image',{request_id:id,port:Number(localStorage.getItem('frame-comfy-port')||8188),project_id:data.project_id||data.title,character_id:c.id||c.character_id||c.name,character_name:c.name,background:c.nonWhiteBackground?'gray':'white',width:c.imageSize?.width||512,height:c.imageSize?.height||1440,prompt:c.prompt,negative_prompt:c.negativePrompt||'',style:data.style||''});applyFrontResult(c,job);render();toast('真实生成任务已提交到本机 ComfyUI')}catch(e){c.frontJob.status='failed';c.frontJob.error=e.message;save();render();toast('提交失败：'+e.message)}finally{frontRequests.delete(c)}};
let checkingFront=false;async function checkFrontJobs(){if(checkingFront)return;checkingFront=true;try{let changed=false;for(const c of data.characters){if(!c.frontJob?.id||!['submitting','queued','running','waiting'].includes(frontState(c))||frontRequests.has(c))continue;try{const previous=JSON.stringify([c.frontJob.id,c.frontJob.status,c.frontJob.image_url,c.frontJob.error]);const job=await frontFetch('/api/front-image/'+c.frontJob.id);applyFrontResult(c,job);if(previous!==JSON.stringify([job.id,job.status,job.image_url,job.error]))changed=true;}catch(e){c.frontJob.last_connection_error=e.message;save();}}if(changed&&tab===0)render();}finally{checkingFront=false}}
setInterval(checkFrontJobs,2500);checkFrontJobs();
const notice=document.querySelector('.notice');notice.textContent='✦ 正面图已接入本机 ComfyUI · 多面图、分镜及视频生成仍待接入。';render();

const charactersBeforeWorkflowLinks=characters;
characters=function(){charactersBeforeWorkflowLinks();const c=data.characters[ci];const generate=document.querySelector('#generate');if(!c||!generate)return;const links=document.createElement('div');links.style.cssText='display:flex;gap:12px;flex-wrap:wrap;margin:13px 0;font-size:11px';const job=c.view==='multi'?null:c.frontJob;const base=job?.id?'/api/front-image/'+job.id+'/workflow':'/api/front-image-template';for(const [text,url,download] of [[job?.id?'查看本次工作流':'查看正面图工作流',base,false],['下载工作流',base+'?download=1',true],['打开 ComfyUI','http://127.0.0.1:'+Number(localStorage.getItem('frame-comfy-port')||8188)+'/',false]]){const a=document.createElement('a');a.textContent=text;a.href=url;a.target='_blank';a.rel='noopener';a.style.color='var(--green)';if(download)a.download='character-workflow.api.json';links.append(a)}generate.after(links)};
render();
